const ForwardButtonSVG = ({onClick, move, transcript, reason = null}) => {
    const [clicked, setClicked] = useState(false)
    let isDisabled = false
    if (!reason || reason === 'score') {
        isDisabled = transcript ? move === transcript.length / 2 : true
    } else {
        isDisabled = move > transcript.length / 2
    }
    const clickHandler = () => {
        setClicked (true)
        setTimeout(() => setClicked(false), 200)
        onClick()
    }
    return(
        <button className = 'replay' title = 'forward' onClick = {clickHandler} disabled = {isDisabled} >
            <svg viewBox="0 0 1024 1024" focusable="false" data-icon="caret-right" width="30px" height="30px" fill = {clicked ? 'white' : "#aca9a9"} stroke= {clicked ? 'white' : "#aca9a9"} aria-hidden="true">
                <path d="M715.8 493.5L335 165.1c-14.2-12.2-35-1.2-35 18.5v656.8c0 19.7 20.8 30.7 35 18.5l380.8-328.4c10.9-9.4 10.9-27.6 0-37z">
                </path>
            </svg>
        </button>
    )
}

