const TimeControl = ({timeControl, inRow = true}) => {
    if (timeControl === 1) {
        return (
            <div className= 'time-control-bullet' style = {!inRow ?  {marginTop: 0} : {}}>
                <BulletIconSVG/>
            </div>
        )
    } 
    if (timeControl === 3 || timeControl === 5) {
        return (
            <div className= 'time-control-blitz' style = {!inRow ?  {marginTop: 0} : {}}>
                <BlitzIconSVG/>
            </div>
        )
    }
    if (timeControl === 10 || timeControl === 15) {
        return (
            <div className= 'time-control-blitz' style = {!inRow ?  {marginTop: 0} : {}}>
                <RapidIconSVG/>
            </div>
        )
    } 
    return (
        <div className= 'time-control-classic' style = {!inRow ?  {marginTop: 0} : {}}>
            <ClassicalIconSVG/>
        </div>
    )
}

const TimeControlTournament = ({timeControl}) => {
    if (timeControl < 3) {
        return (
            <div className= 'time-control-bullet'>
                <BulletIconSVG/>
            </div>
        )
    } 
    if (timeControl < 10) {
        return (
            <div className= 'time-control-blitz'>
                <BlitzIconSVG/>
            </div>
        )
    }
    if (timeControl < 20) {
        return (
            <div className= 'time-control-blitz'>
                <RapidIconSVG/>
            </div>
        )
    } 
    return (
        <div className= 'time-control-classic'>
            <ClassicalIconSVG/>
        </div>
    )
}

